"""Generate CYPHER.md from the live tool registry — the doc can never drift
from the queries, because the doc IS the queries.

Run:  python scripts/gen_docs.py
"""

import inspect
import re
from pathlib import Path

import ledgerlens.tools as tools_module
from ledgerlens.tools import TOOLS

CONST_RE = re.compile(r"_Q_[A-Z0-9_]+")

ROOT = Path(__file__).parent.parent


def main() -> None:
    lines = [
        "# The Cypher the product depends on",
        "",
        "> Generated by `scripts/gen_docs.py` from the live tool registry in",
        "> `ledgerlens/tools.py`. Every query below is the exact string the tool",
        "> runs; where a tool composes several queries, all are shown.",
        "",
        "The model never writes Cypher — it picks a tool and fills validated",
        "arguments. These are the hand-written queries it executes against the",
        "tenant graph (FalkorDB 6.x, `GRAPH.RO_QUERY` for reads, `GRAPH.QUERY`",
        "for audited writes).",
        "",
    ]
    for tool in TOOLS.values():
        lines.append(f"## `{tool.name}` ({tool.kind})")
        lines.append("")
        lines.append(f"{tool.description}")
        lines.append("")
        src = inspect.getsource(tool.handler)
        const_names = list(dict.fromkeys(CONST_RE.findall(src)))
        named_queries = []
        for name in const_names:
            value = getattr(tools_module, name, None)
            if isinstance(value, str) and value.strip():
                named_queries.append((name, value.strip()))
        if named_queries:
            for name, q in named_queries:
                lines.append(f"**{name}**")
                lines.append("")
                lines.append("```cypher")
                lines.append(q)
                lines.append("```")
                lines.append("")
        else:
            lines.append("_(query composed inline — see the handler source in `ledgerlens/tools.py`)_")
            lines.append("")
    out = ROOT / "CYPHER.md"
    out.write_text("\n".join(lines))
    print(f"wrote {out} ({len(lines)} lines, {len(TOOLS)} tools)")


if __name__ == "__main__":
    main()
